questions.push(
  question("BIO_R4_Q_S081_01", "BIO_R4_S081", "foundation", 0, "下列哪一組構造都屬於中樞神經系統？", ["腦與脊髓", "腦與腦神經", "脊髓與脊神經", "腦神經與脊神經"], ["腦和脊髓共同構成中樞神經系統。", "腦神經位於中樞之外，屬周圍神經。", "脊神經屬周圍神經，不是中樞構造。", "兩者都屬周圍神經系統的構造。"], ["腦與脊髓共同負責重要訊息的整合與傳遞，兩者都屬中樞神經系統。", "腦神經與脊神經都屬周圍神經，因此含有其中任一者的組合都不能全歸入中樞。"], ["辨識"], "文字分類", ["把所有神經都視為中樞"]),
  question("BIO_R4_Q_S081_02", "BIO_R4_S081", "foundation", 1, "皮膚受器產生的訊息要送到脊髓，主要經過下列何者？", ["骨骼", "周圍神經", "血管", "肌腱"], ["骨骼提供支撐，並不傳送神經訊息。", "周圍神經連接受器與中樞，可傳入訊息。", "血管運送血液，不是刺激訊息的傳導路徑。", "肌腱連接肌肉與骨骼，不負責傳入感覺。"], ["題幹問受器到中樞的連接，符合周圍神經的傳入功能。", "骨骼負責支撐、血管運送血液、肌腱連接肌肉與骨骼，三者都不傳送皮膚受器的神經訊息。"], ["理解"], "生活情境", ["把血液運輸當成神經傳導"]),
  question("BIO_R4_Q_S081_03", "BIO_R4_S081", "foundation", 2, "下列何者最能描述脊髓的一項功能？", ["製造紅血球", "分泌消化液", "傳遞腦與身體間的訊息", "把養分送到全身"], ["紅血球主要由骨髓中的造血組織產生。", "消化液由消化腺或消化器官相關細胞分泌。", "脊髓是腦與身體間重要的訊息傳導通道。", "養分主要隨循環系統的血液運送。"], ["脊髓位於腦與身體的神經路徑之間，可傳遞上行感覺訊息與下行動作命令。", "紅血球由造血組織製造、消化液由相關腺體分泌、養分由血液運送，都不是脊髓的功能。"], ["辨識"], "功能判斷", ["混淆不同器官系統功能"]),
  question("BIO_R4_Q_S081_04", "BIO_R4_S081", "standard", 3, "某人腳趾受刺激後，訊息沿神經傳到脊髓。此段神經最適合歸入哪一類？", ["負責整合訊息的腦部構造", "位於中樞的脊髓構造", "由腦與脊髓組成的中樞神經系統", "連接腳趾受器與脊髓的周圍神經系統"], ["腦部負責整合，並非題述連接腳趾的傳導神經。", "脊髓是訊息到達的中樞構造，不是沿途神經。", "中樞包含腦和脊髓，不含連接腳趾的神經。", "連接腳趾受器與脊髓的神經屬周圍神經。"], ["依端點判斷，腳趾到脊髓的連接線位於中樞之外。", "題幹已區分神經與脊髓，故「周圍神經系統」是唯一合理分類。"], ["分類", "應用"], "身體路徑", ["把連到中樞的神經也算入中樞"]),
  question("BIO_R4_Q_S081_05", "BIO_R4_S081", "standard", 0, "騎車者看見前方障礙並決定煞車，負責判讀視覺訊息與形成決策的主要構造為何？", ["整合視覺訊息並形成決策的腦", "把命令傳向肢體的脊神經", "執行煞車動作的腿部肌肉", "保護眼球表面的外膜構造"], ["腦能整合視覺訊息並形成有意識的動作決策。", "脊神經負責傳導，不是主要的視覺判讀中心。", "腿部肌肉執行動作，不負責形成煞車決策。", "眼球外膜有保護作用，不能完成訊息決策。"], ["題幹包含判讀與決策，兩者指向中樞中的腦。", "脊神經只傳導命令、腿部肌肉執行煞車、眼球外膜保護眼球，都不能形成視覺判讀與決策。"], ["理解", "應用"], "交通情境", ["把受器或肌肉當作決策中心"]),
  question("BIO_R4_Q_S081_06", "BIO_R4_S081", "standard", 1, "若連接右手肌肉的某條周圍神經受損，最可能直接出現哪種情況？", ["腦完全不能產生動作命令", "命令難以完整傳到右手肌肉", "脊髓立即消失所有功能", "左手必定同時失去感覺"], ["局部周圍神經受損不表示腦無法產生命令。", "受損路徑會妨礙中樞命令到達其連接的肌肉。", "單一周圍神經損傷不會使整個脊髓失去功能。", "右手局部路徑受損不能推出左手必定受影響。"], ["依受損位置追蹤，直接影響是右手命令的傳出路徑。", "局部右手神經受損不會使腦停止下令、脊髓全面失能，也不能推出左手感覺必然消失。"], ["因果推論"], "受損情境", ["把局部神經損傷推成全身失能"]),
  question("BIO_R4_Q_S081_07", "BIO_R4_S081", "standard", 2, "下列哪一敘述正確比較中樞與周圍神經系統？", ["兩者都只負責感覺，不控制動作", "中樞只傳導，周圍只整合", "中樞負責整合，周圍負責連接與傳導", "周圍只分布在四肢，不分布在頭部"], ["神經系統也能控制肌肉與腺體的反應。", "整合主要由中樞完成，兩者分工敘述顛倒。", "此敘述符合兩系統在訊息處理中的基本分工。", "腦神經分布於頭部，也是周圍神經的一部分。"], ["中樞整合、周圍連接與傳導的敘述同時符合兩系統定義。", "頭部也有周圍神經，故不能以是否位於四肢作判準。"], ["比較"], "概念對照", ["顛倒中樞與周圍分工"]),
  question("BIO_R4_Q_S081_08", "BIO_R4_S081", "advanced", 3, "研究者發現受試者能感到足部被碰觸，但腦發出的抬腳命令無法到達足部肌肉。哪項推論最合理？", ["足部受器必定完全失效", "所有傳入神經都已中斷", "腦必定不能形成抬腳命令", "通往足部肌肉的傳出路徑可能受損"], ["仍能感到碰觸，表示受器並非必定完全失效。", "感覺能形成，代表至少有傳入路徑仍可運作。", "題幹已指出腦發出命令，不能推論腦無法形成命令。", "感覺保留而動作命令受阻，符合傳出路徑受損。"], ["將傳入與傳出分開檢驗，可定位在通往肌肉的傳出路徑。", "足部仍有觸覺可排除受器全失效與傳入全中斷；腦已發出命令也排除命令未形成。"], ["證據推論"], "臨床情境", ["不區分傳入與傳出路徑"]),
  question("BIO_R4_Q_S081_09", "BIO_R4_S081", "advanced", 0, "甲受傷後手能收縮，但無法把手部觸覺訊息送達中樞。依此資料，哪項判斷最受支持？", ["傳入訊息的周圍神經路徑受影響", "手部所有肌肉都已壞死", "腦與脊髓都完全停止運作", "傳出命令的路徑必定完全中斷"], ["動作仍可發生而觸覺傳入受阻，支持傳入路徑受影響。", "手能收縮與所有肌肉壞死的說法互相矛盾。", "局部觸覺異常不足以推論整個中樞停止運作。", "手仍能收縮，表示傳出路徑不必然完全中斷。"], ["利用保留的動作功能排除肌肉與傳出路徑全面失效。", "手仍能收縮顯示肌肉與傳出功能尚可，觸覺卻送不到中樞，因此證據指向傳入路徑。"], ["分析"], "功能診斷", ["由單一症狀過度推論"]),
  question("BIO_R4_Q_S081_10", "BIO_R4_S081", "advanced", 1, "某訊息依序通過皮膚受器、甲、脊髓、腦。若甲為神經構造，甲最可能是什麼？", ["大腦皮質", "周圍神經", "脊髓內部", "腿部骨骼肌"], ["大腦皮質位於流程末端的腦內，不在受器與脊髓之間。", "周圍神經可連接皮膚受器與脊髓，位置符合流程。", "流程已另列脊髓，甲不應再是同一中樞構造。", "骨骼肌是動器官，不是把感覺送入脊髓的神經。"], ["以甲的前後端點判斷，它必須連接受器與脊髓。", "大腦皮質和脊髓內部都屬中樞，骨骼肌則非神經；周圍神經才位在受器與脊髓之間。"], ["路徑分析"], "序列模型", ["只看名稱不看流程位置"]),
  question("BIO_R4_Q_S081_11", "BIO_R4_S081", "transfer", 2, "工程師設計機器人：感測器連到中央處理器，處理器再經導線控制馬達。若類比人體神經系統，中央處理器最接近哪個部分？", ["受器", "周圍神經", "中樞神經系統", "肌肉與腺體"], ["感測器本身才較接近接收刺激的受器。", "導線較接近負責連接與傳導的周圍神經。", "中央處理器整合輸入並形成命令，功能近似中樞。", "馬達才較接近執行反應的肌肉等動器官。"], ["類比應依功能對應，中央處理器的整合角色符合中樞。", "感測器負責接收、導線負責傳送、馬達負責執行；中央處理器整合輸入並形成命令，對應中樞。"], ["類比", "遷移"], "工程模型", ["依外形而非功能類比"]),
  question("BIO_R4_Q_S081_12", "BIO_R4_S081", "transfer", 3, "一套校園警報系統的各感測器都正常，控制室也能作出判斷，但某區警鈴收不到啟動訊號。若對照神經系統，最應優先檢查哪項？", ["感測器是否能接收刺激", "控制室是否存在", "其他區域的警鈴音量", "控制室通往該區警鈴的傳出線路"], ["題幹已說明感測器正常，並非優先疑點。", "控制室能作出判斷，表示其存在且可處理訊息。", "其他區域音量不能解釋特定區收不到訊號。", "命令已形成卻未到達，應檢查特定傳出線路。"], ["先利用已知正常項目排除受器與中樞，再定位傳出連結。", "此情境對應中樞命令無法經周圍路徑到達動器官。"], ["系統診斷", "遷移"], "警報系統類比", ["忽略題幹已知條件"]),
);

